// One run = one push (to one repo) or one full sync (all repos).
const input = $input.first().json;
const body = input.body;
if (body && body.repository) {
  const changed = new Set();
  const removed = new Set();
  for (const commit of body.commits || []) {
    for (const p of [...(commit.added || []), ...(commit.modified || [])]) { changed.add(p); removed.delete(p); }
    for (const p of commit.removed || []) { removed.add(p); changed.delete(p); }
  }
  return [{ json: {
    mode: 'push',
    repo: body.repository.name,
    branch: (body.ref || '').replace('refs/heads/', ''),
    changed: [...changed],
    removed: [...removed],
  } }];
}
return [{ json: { mode: 'full' } }];

const YAML = require('yaml');
const schema = YAML.parse($('Get taxonomy').first().json.data);
const plan = $('Plan sync').first().json;
const out = [];
for (const [source, cfg] of Object.entries(schema.sources)) {
  const [owner, repo] = cfg.repo.split('/');
  // Pushes to other branches or repos are ignored.
  if (plan.mode === 'push' && (repo !== plan.repo || plan.branch !== cfg.branch)) continue;
  out.push({ json: { source, owner, repo, branch: cfg.branch, mode: plan.mode,
    changed: plan.changed || [], removed: plan.removed || [] } });
}
return out;

const YAML = require('yaml');
const schema = YAML.parse($('Get taxonomy').first().json.data);

const toRe = (glob) => new RegExp('^' + glob
  .replace(/[.+^${}()|[\]\\]/g, '\\$&')
  .replace(/\*\*\//g, '\u0000').replace(/\*\*/g, '\u0001').replace(/\*/g, '[^/]*')
  .replace(/\u0000/g, '(?:.*/)?').replace(/\u0001/g, '.*') + '$');
const matches = (path, globs) => (globs || []).some((g) => toRe(g).test(path));

const out = [];
$input.all().forEach((item, i) => {
  const r = $('Repos to scan').itemMatching(i).json;
  const cfg = schema.sources[r.source];
  const inScope = (p) => matches(p, cfg.include) && !matches(p, cfg.exclude);
  const base = { source: r.source, owner: r.owner, repo: r.repo, branch: r.branch, mode: r.mode };
  let paths = (item.json.tree || []).filter((t) => t.type === 'blob').map((t) => t.path).filter(inScope);
  if (r.mode === 'push') paths = paths.filter((p) => r.changed.includes(p));
  for (const path of paths) out.push({ json: { ...base, path, removed: false } });
  if (r.mode === 'push') {
    for (const path of r.removed.filter(inScope)) out.push({ json: { ...base, path, removed: true } });
  }
});
return out;

// Normalize each file and check it against taxonomy/schema.yaml.
// A document reaches search only when it has no errors. Stale content stays searchable and is flagged.
const YAML = require('yaml');
const crypto = require('crypto');
const schema = YAML.parse($('Get taxonomy').first().json.data);
const F = schema.fields;
const CRAFTS = ['metalworking', 'leatherworking', 'cooking'];
const today = new Date();

const toRe = (glob) => new RegExp('^' + glob
  .replace(/[.+^${}()|[\]\\]/g, '\\$&')
  .replace(/\*\*\//g, '\u0000').replace(/\*\*/g, '\u0001').replace(/\*/g, '[^/]*')
  .replace(/\u0000/g, '(?:.*/)?').replace(/\u0001/g, '.*') + '$');
const matches = (path, globs) => (globs || []).some((g) => toRe(g).test(path));

function publicUrl(f, fm) {
  const p = f.path.replace(/\.(mdx?|ya?ml)$/, '');
  if (f.source === 'portfolio') return 'https://strahinjamilosevic.com/' + p.replace(/(^|\/)index$/, '');
  if (f.source === 'all-maker-blog') {
    if (p.startsWith('blog/')) return fm.slug ? `https://all-maker.com/blog/${String(fm.slug).replace(/^\//, '')}` : null;
    if (fm.slug && String(fm.slug).startsWith('/')) return 'https://all-maker.com/docs' + fm.slug;
    return 'https://all-maker.com/' + p.replace(/\/index$/, '');
  }
  return null; // careers is private
}

function toText(body) {
  return body
    .replace(/^\s*(import|export)\s.*$/gm, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/\{\/\*[\s\S]*?\*\/\}/g, '')
    .replace(/<\/?[A-Za-z][^>]*>/g, ' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function validate(ctx, issues) {
  const ct = ctx.content_type;
  for (const [name, spec] of Object.entries(F)) {
    const v = ctx[name];
    const empty = v === undefined || v === null || (Array.isArray(v) && v.length === 0);
    if (spec.required && empty) issues.push(`Missing required field \`${name}\`.`);
    if ((spec.required_for || []).includes(ct) && empty) issues.push(`Missing \`${name}\`, required for ${ct}.`);
    if (!empty && (spec.not_for || []).includes(ct)) issues.push(`\`${name}\` is not allowed on ${ct}.`);
    if (!empty && spec.applies_to && !spec.applies_to.includes(ct)) issues.push(`\`${name}\` only applies to ${spec.applies_to.join(', ')}.`);
    if (empty || !spec.values) continue;
    const vals = Array.isArray(v) ? v : [v];
    const bad = vals.filter((x) => !spec.values.includes(x));
    if (bad.length) issues.push(`\`${name}\` has values outside the vocabulary: ${bad.join(', ')}. Use an existing value or propose a new one.`);
    if (Array.isArray(v) && (v.length < (spec.min ?? 0) || v.length > (spec.max ?? Infinity))) {
      issues.push(`\`${name}\` has ${v.length} values. Allowed: ${spec.min ?? 0} to ${spec.max ?? 'any'}.`);
    }
  }
  for (const k of Object.keys(ctx)) if (!F[k]) issues.push(`Unknown field \`${k}\`.`);
  const domain = ctx.domain || [];
  const tags = ctx.tags || [];
  if (domain.includes('crafting') && !(tags.includes('crafting') && tags.some((t) => CRAFTS.includes(t)))) {
    issues.push('Crafting content needs `tags: [crafting, <craft>]`.');
  }
  if (tags.length && !domain.includes('crafting')) issues.push('Craft tags are only allowed in the crafting domain.');
}

const docs = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const f = $('Select files').itemMatching(i).json;
  const doc = {
    doc_id: `${f.source}:${f.path}`, source: f.source, repo: `${f.owner}/${f.repo}`, path: f.path, mode: f.mode,
    github_url: `https://github.com/${f.owner}/${f.repo}/blob/${f.branch}/${f.path}`,
    removed: f.removed, issues: [], warnings: [], searchable: false, stale: false,
  };
  docs.push(doc);
  if (f.removed) continue;

  const raw = $('Get file').itemMatching(i).json.data;
  if (typeof raw !== 'string') { doc.issues.push('The file could not be fetched from GitHub.'); continue; }
  try { doc.updated_at = JSON.parse(items[i].json.data)[0].commit.committer.date.slice(0, 10); } catch (e) { doc.updated_at = null; }

  const secret = (schema.secret_patterns || []).find((p) => new RegExp(p.replace('(?i)', ''), p.startsWith('(?i)') ? 'i' : '').test(raw));
  if (secret) { doc.issues.push('Possible credential found. The file was not ingested. Remove the secret, rotate it, and push again.'); continue; }

  const isYaml = /\.ya?ml$/.test(f.path);
  let fm = {};
  let body = raw;
  if (!isYaml) {
    const m = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
    if (m) {
      try { fm = YAML.parse(m[1]) || {}; } catch (e) { doc.issues.push(`Frontmatter is not valid YAML: ${e.message.split('\n')[0]}`); }
      body = raw.slice(m[0].length);
    }
  }
  let ctx = fm.context;
  const def = (schema.path_defaults || []).find((d) => d.source === f.source && toRe(d.path).test(f.path));
  if (!ctx && def) ctx = { ...def.fields, last_reviewed: doc.updated_at };
  if (!ctx) { doc.issues.push('No `context:` block in the frontmatter. Tag the file, see taxonomy/contributor-guide.md.'); continue; }
  validate(ctx, doc.issues);

  const ct = ctx.content_type;
  const limit = (schema.freshness_days || {})[ct];
  if (limit) {
    if (!ctx.last_reviewed) doc.issues.push(`Missing \`last_reviewed\`. ${ct} is reviewed every ${limit} days.`);
    else {
      const age = Math.floor((today - new Date(ctx.last_reviewed)) / 86400000);
      if (age > limit) {
        doc.stale = true;
        doc.warnings.push(`Stale: last reviewed ${ctx.last_reviewed}, ${age} days ago. Limit for ${ct}: ${limit} days. Review the content and set \`last_reviewed\` to today.`);
      }
    }
  }
  if (ctx.status === 'stub') doc.warnings.push('Stub: write the content, then set `status: published`.');

  const h1 = (body.match(/^#\s+(.+)$/m) || [])[1];
  const file = f.path.split('/').pop().replace(/\.\w+$/, '');
  doc.title = fm.title || (fm.company && `${fm.company} achievements`) || (isYaml && 'Profile facts') || h1
    || `${f.path.split('/').slice(-2, -1)[0] || ''} ${file}`.trim();

  doc.url = publicUrl(f, fm);
  doc.context = ctx;
  doc.text = [doc.title, fm.description, isYaml ? raw : toText(body)].filter(Boolean).join('\n\n');
  doc.hash = crypto.createHash('sha256').update(doc.text.toLowerCase().replace(/\s+/g, ' ')).digest('hex');
  doc.searchable = doc.issues.length === 0 && ctx.status === 'published';
}

// Rules across documents: exact duplicates and canonical targets.
const byHash = {};
for (const d of docs) if (d.hash) (byHash[d.hash] = byHash[d.hash] || []).push(d);
for (const group of Object.values(byHash)) {
  if (group.length > 1 && !group.some((d) => d.context.canonical)) {
    for (const d of group) d.issues.push(`Duplicate content: identical to ${group.filter((x) => x !== d).map((x) => x.doc_id).join(', ')}. Set \`canonical\` on the copy.`);
  }
}
if (docs[0] && docs[0].mode === 'full') {
  const ids = new Set(docs.map((d) => d.doc_id));
  for (const d of docs) {
    const targets = [].concat((d.context || {}).canonical || []);
    const missing = targets.filter((t) => !ids.has(t));
    if (missing.length) d.issues.push(`\`canonical\` points to documents that do not exist: ${missing.join(', ')}.`);
  }
}
for (const d of docs) if (d.issues.length) d.searchable = false;
return docs.map((d) => ({ json: d }));

// One review-queue Issue per document. Create, update, or close it to match the latest check.
const REPO = 'https://api.github.com/repos/strahinjamilosevic/all-maker-context';
const docs = $('Parse and validate').all().map((i) => i.json);
let open = [];
try { open = JSON.parse($('Get open review issues').first().json.data); } catch (e) { open = []; }
const byDoc = {};
for (const issue of open) {
  const m = (issue.body || '').match(/<!-- doc_id: (.+?) -->/);
  if (m) byDoc[m[1]] = issue;
}
const actions = [];
const seen = new Set();
for (const d of docs) {
  seen.add(d.doc_id);
  const existing = byDoc[d.doc_id];
  const findings = [...d.issues, ...d.warnings];
  if (findings.length) {
    const body = [
      `<!-- doc_id: ${d.doc_id} -->`,
      `**Document:** [\`${d.path}\`](${d.github_url}) in \`${d.repo}\``,
      d.url ? `**Live page:** ${d.url}` : null,
      `**In search:** ${d.searchable ? 'yes' + (d.stale ? ', marked stale' : '') : d.issues.length ? 'no, until the errors are fixed' : `no, status is ${(d.context || {}).status}`}`,
      '',
      d.issues.length ? '**Errors** (block search):' : null,
      ...d.issues.map((x) => `- [ ] ${x}`),
      d.warnings.length ? '**Warnings:**' : null,
      ...d.warnings.map((x) => `- [ ] ${x}`),
      '',
      'Fix the file in its source repo. The next sync updates or closes this Issue.',
    ].filter((x) => x !== null).join('\n');
    if (!existing) {
      actions.push({ method: 'POST', url: `${REPO}/issues`, body: { title: `Review: ${d.doc_id}`, body, labels: ['review-queue'] } });
    } else if (existing.body !== body) {
      actions.push({ method: 'PATCH', url: `${REPO}/issues/${existing.number}`, body: { body } });
    }
  } else if (existing) {
    actions.push({ method: 'PATCH', url: `${REPO}/issues/${existing.number}`, body: { state: 'closed', state_reason: 'completed' } });
  }
}
// Full sync: close Issues for documents that no longer exist.
if (docs[0] && docs[0].mode === 'full') {
  for (const [id, issue] of Object.entries(byDoc)) {
    if (!seen.has(id)) actions.push({ method: 'PATCH', url: `${REPO}/issues/${issue.number}`, body: { state: 'closed', state_reason: 'not_planned' } });
  }
}
return actions.map((a) => ({ json: a }));

// Full sync only: remove chunks of documents that are gone from the source repos.
const docs = $('Parse and validate').all().map((i) => i.json);
if (!docs.length || docs[0].mode !== 'full') return [];
const bySource = {};
for (const d of docs) (bySource[d.source] = bySource[d.source] || []).push(d.doc_id);
return Object.entries(bySource).map(([source, ids]) => ({ json: { filter: {
  must: [{ key: 'metadata.source', match: { value: source } }],
  must_not: [{ key: 'metadata.doc_id', match: { any: ids } }],
} } }));
